<?php $pageTitle='Generate seating';$roomCapacity=array_sum(array_map(static fn($room)=>(int)$room['usable_capacity'],$rooms)); ?>
<div class="seating-generator-page seating-enter">
  <section class="generator-heading"><div><a href="<?= e(url('seating')) ?>"><span aria-hidden="true">←</span> Seating register</a><p class="seating-overline">Automated allocation</p><h1>Build a mixed seating plan</h1><p>Select an examination session and the rooms available to the allocation engine.</p></div><div class="generator-method"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="45" height="45"><div><strong>Fair distribution method</strong><span>Normalized roll order with programme interleaving</span></div></div></section>
  <?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
  <div class="generator-workspace"><form id="seating-generator" class="generator-builder" method="post" action="<?= e(url('seating/generate')) ?>"><?= csrf_field() ?><input type="hidden" name="cycle_id" value="<?= $cycleId ?>"><input id="exam-date" type="hidden" name="exam_date"><input id="shift-id" type="hidden" name="shift_id">
    <section class="generator-step <?= $cycleId?'complete':'' ?>"><header><span>01</span><div><h2>Examination cycle</h2><p>Choose the academic examination being allocated.</p></div><b class="step-state" aria-hidden="true"></b></header><div class="step-body"><label for="cycle-select">Active cycle</label><select id="cycle-select" required><option value="">Select examination cycle</option><?php foreach($cycles as $cycle):?><option value="<?= (int)$cycle['id'] ?>" <?= $cycleId===(int)$cycle['id']?'selected':'' ?>><?= e($cycle['name']) ?></option><?php endforeach;?></select><small>Changing the cycle reloads its scheduled sessions.</small><?php if(!$cycles):?><div class="generator-inline-empty">No active cycles are available. Create a cycle and schedule papers first.</div><?php endif;?></div></section>
    <section class="generator-step <?= $cycleId?'ready':'locked' ?>" id="session-step"><header><span>02</span><div><h2>Examination session</h2><p>Demand is calculated from eligible students.</p></div><b class="step-state" aria-hidden="true"></b></header><div class="step-body"><label for="session-select">Date and shift</label><select id="session-select" name="session" <?= $cycleId?'required':'disabled' ?>><option value="">Select date and shift</option><?php foreach($sessions as $session):?><option value="<?= e($session['exam_date'].'|'.$session['shift_id']) ?>" data-eligible="<?= (int)$session['eligible_count'] ?>" data-label="<?= e(date('d M Y',strtotime($session['exam_date'])).' | '.$session['shift_name']) ?>"><?= e(date('D, d M Y',strtotime($session['exam_date'])).' | '.$session['shift_name'].' | '.$session['eligible_count'].' eligible students') ?></option><?php endforeach;?></select><?php if($cycleId&&!$sessions):?><div class="generator-inline-empty">This cycle has no scheduled sessions with eligible students.</div><?php endif;?></div></section>
    <section class="generator-step <?= $cycleId?'ready':'locked' ?>" id="rooms-step"><header><span>03</span><div><h2>Available rooms</h2><p>Select enough usable seats to cover the session demand.</p></div><b class="step-state" aria-hidden="true"></b></header><div class="step-body"><div class="room-tools"><span><b id="selected-room-count">0</b> rooms selected</span><button id="select-all-rooms" type="button">Select all</button></div><fieldset <?= $cycleId?'':'disabled' ?>><legend class="sr-only">Available rooms</legend><div class="room-choices enhanced"><?php foreach($rooms as $room):?><label><input type="checkbox" name="room_ids[]" value="<?= (int)$room['id'] ?>" data-capacity="<?= (int)$room['usable_capacity'] ?>"><span class="room-check" aria-hidden="true"></span><span class="room-detail"><strong><?= e($room['code']) ?></strong><small><?= e($room['building']) ?></small></span><span class="room-capacity"><b><?= number_format((int)$room['usable_capacity']) ?></b><small>usable seats</small></span></label><?php endforeach;?></div></fieldset><?php if(!$rooms):?><div class="generator-inline-empty">No active rooms are available. Add room layouts before generating seating.</div><?php endif;?></div></section>
  </form><aside class="allocation-readiness"><div class="readiness-brand"><div class="seat-map-symbol" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div><span>Allocation readiness</span></div><h2 id="summary-session">Choose a session</h2><div class="capacity-gauge" aria-label="Selected room capacity"><div><span id="capacity-bar"></span></div><p><strong id="selected-capacity">0</strong><span>of <b id="eligible-demand">0</b> required seats</span></p></div><dl><div><dt>Selected rooms</dt><dd id="summary-rooms">0</dd></div><div><dt>Total active capacity</dt><dd><?= number_format($roomCapacity) ?></dd></div><div><dt>Allocation order</dt><dd>Priority, then room code</dd></div><div><dt>Mixing rule</dt><dd>Programme interleaving</dd></div></dl><div id="readiness-message" class="readiness-message"><b class="ui-icon icon-info" aria-hidden="true"></b><span>Select a session and rooms to check capacity.</span></div><button id="generate-button" class="generate-action" type="submit" form="seating-generator" disabled><span><b class="ui-icon icon-spark" aria-hidden="true"></b>Generate allocation</span><b aria-hidden="true">→</b></button><small class="readiness-note">A new draft version is created. Existing versions remain unchanged.</small></aside></div>
</div>
<script>(()=>{const cycle=document.getElementById('cycle-select'),session=document.getElementById('session-select'),rooms=[...document.querySelectorAll('input[name="room_ids[]"]')],all=document.getElementById('select-all-rooms'),capacity=document.getElementById('selected-capacity'),demand=document.getElementById('eligible-demand'),bar=document.getElementById('capacity-bar'),count=document.getElementById('selected-room-count'),summaryRooms=document.getElementById('summary-rooms'),summarySession=document.getElementById('summary-session'),message=document.getElementById('readiness-message'),button=document.getElementById('generate-button'),date=document.getElementById('exam-date'),shift=document.getElementById('shift-id');cycle?.addEventListener('change',()=>{if(cycle.value)location.href='<?= e(url('seating/generate?cycle_id=')) ?>'+encodeURIComponent(cycle.value);});const update=()=>{const option=session?.options[session.selectedIndex],parts=(session?.value||'').split('|'),required=Number(option?.dataset.eligible||0),selected=rooms.filter(room=>room.checked),seats=selected.reduce((sum,room)=>sum+Number(room.dataset.capacity),0),ready=required>0&&selected.length>0&&seats>=required;date.value=parts[0]||'';shift.value=parts[1]||'';capacity.textContent=seats.toLocaleString();demand.textContent=required.toLocaleString();count.textContent=selected.length;summaryRooms.textContent=selected.length;summarySession.textContent=option?.dataset.label||'Choose a session';bar.style.width=(required?Math.min(100,seats/required*100):0)+'%';message.className='readiness-message '+(ready?'ready':seats&&required?'warning':'');message.querySelector('span').textContent=ready?`${seats-required} spare seats. Ready to generate.`:required&&seats?`${required-seats} more seats are required.`:'Select a session and rooms to check capacity.';button.disabled=!ready;all.textContent=selected.length===rooms.length&&rooms.length?'Clear all':'Select all';};session?.addEventListener('change',update);rooms.forEach(room=>room.addEventListener('change',update));all?.addEventListener('click',()=>{const select=rooms.some(room=>!room.checked);rooms.forEach(room=>room.checked=select);update();});update();})();</script>
